import {appendFileSync,readFileSync,writeFileSync} from 'node:fs'
let calls = 0
const emit = value => appendFileSync("<OUTPUT_DIR>/trace.jsonl", JSON.stringify(value)+'\n')
export default { test: { projects: [{test:{name:'node',mode:'development',include:['contract.test.mjs']}}], maxWorkers:1, coverage:{enabled:true,provider:'v8',include:['subject.mjs'],reporter:['json','json-summary','lcovonly'],reportsDirectory:'coverage',thresholds:{"lines": 0, functions:0, statements:0, branches:0, autoUpdate:function(value,previous){ calls++; emit({kind:'format',calls,value,previous,receiver:this===undefined}); ; return Math.floor(value) }}}}}

